-- ShahkotPK v11.2.0 — User Experience & Smart Interaction Suite
CREATE TABLE IF NOT EXISTS ux_preferences_v1120 (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL DEFAULT 0,enabled TINYINT NOT NULL DEFAULT 1,target_theme VARCHAR(80) NOT NULL DEFAULT 'advanced_landing_theme_studio',mobile_bottom_nav TINYINT NOT NULL DEFAULT 1,sticky_detail_actions TINYINT NOT NULL DEFAULT 1,skeleton_loaders TINYINT NOT NULL DEFAULT 1,instant_feedback TINYINT NOT NULL DEFAULT 1,guest_memory TINYINT NOT NULL DEFAULT 1,form_autosave TINYINT NOT NULL DEFAULT 1,smart_prefetch TINYINT NOT NULL DEFAULT 1,network_aware TINYINT NOT NULL DEFAULT 1,error_recovery TINYINT NOT NULL DEFAULT 1,accessibility TINYINT NOT NULL DEFAULT 1,dark_mode TINYINT NOT NULL DEFAULT 0,reduced_motion_auto TINYINT NOT NULL DEFAULT 1,feedback_widget TINYINT NOT NULL DEFAULT 1,ux_analytics TINYINT NOT NULL DEFAULT 1,analytics_sample_rate INT NOT NULL DEFAULT 20,max_prefetch_per_page INT NOT NULL DEFAULT 8,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_ux1120_tenant(tenant_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ux_events_v1120 (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL DEFAULT 0,user_id BIGINT UNSIGNED NULL,event_key VARCHAR(80) NOT NULL,page_path VARCHAR(500) NOT NULL,meta_json JSON NULL,ip_hash CHAR(64) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_ux1120_event(tenant_id,event_key,created_at),KEY idx_ux1120_time(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ux_feedback_v1120 (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,tenant_id BIGINT UNSIGNED NOT NULL DEFAULT 0,user_id BIGINT UNSIGNED NULL,page_path VARCHAR(500) NOT NULL,is_helpful TINYINT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_ux1120_feedback(tenant_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO settings(setting_key,setting_value) VALUES ('installed_app_version','11.2.0'),('public_runtime_version','11.2.0'),('user_experience_version','11.2.0'),('active_landing_ux_target','advanced_landing_theme_studio') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
